// policy-card.ts: the rule templates of the Policy Card builder
// (/toolkit/policy-card). Each template is one governance rule from the curated
// set: what it states, the effect it has, where it is enforced, the failure
// mode it addresses, the obligations it helps evidence by default and the
// parameters a reader sets. The executable side of each template (the Rego
// module and its tests, the Cedar stub and its tests, the example input and the
// CI hook) is generated by public/toolkit/policy-card-core.js, which reads this
// data from the page's JSON island; tests/policy-card.spec.ts checks that the
// two agree template by template.
//
// This file imports nothing, so scripts/policy-card-samples.mjs can load it
// under `node --experimental-strip-types` to write the committed samples in
// public/templates/policy-cards/.
//
// `{name}` in `statement` and `condition` is replaced with the parameter's
// value. Default obligation ids are stable ids from src/data/frameworks.ts
// (the page fails the build on an unknown id). Mappings are illustrative, not a
// claim of conformity.

export type PolicyEffect = 'deny' | 'allow' | 'require_approval' | 'alert';
export type EnforcementPoint = 'pre_merge' | 'deploy' | 'runtime' | 'periodic';

/** How a parameter is entered and checked.
 * - `token`: one word-like value (letters, digits and . _ : / @ + -).
 * - `tokens`: a comma-separated list of tokens (may be empty only if `optional`).
 * - `int`: a whole number between `min` and `max`.
 * - `decimal`: a number above zero with at most four decimal places.
 * - `path`: a dot path into the input document, snake_case segments.
 * - `operator`: one of the custom-rule comparison operators.
 * - `value`: a token, a number or true/false, read by the operator. */
export type ParamKind = 'token' | 'tokens' | 'int' | 'decimal' | 'path' | 'operator' | 'value';

export interface PolicyCardParam {
  key: string;
  label: string;
  hint: string;
  kind: ParamKind;
  default: string;
  optional?: boolean;
  min?: number;
  max?: number;
}

export interface PolicyCardTemplate {
  /** Kebab-case id; the link state and the sample folder use it. */
  id: string;
  /** The rule, as a short title. */
  title: string;
  /** One line under the title in the picker. */
  summary: string;
  /** The rule in one sentence; `{param}` placeholders are filled in. */
  statement: string;
  /** The condition in plain words; the engine module is authoritative. */
  condition: string;
  effect: PolicyEffect;
  enforcementPoints: readonly EnforcementPoint[];
  failureMode: string;
  /** Defaults for the card fields. */
  ruleId: string;
  cardId: string;
  cardTitle: string;
  appliesTo: readonly string[];
  sourcePolicy: string;
  obligations: readonly string[];
  /** The chapter 05 pattern the rule builds (slug under /patterns). */
  pattern: string;
  params: readonly PolicyCardParam[];
}

/** Operators of the custom rule, with the words the card uses for them. */
export const customOperators = [
  { id: 'missing', label: 'is missing', needsValue: false },
  { id: 'equals', label: 'equals', needsValue: true },
  { id: 'not_equals', label: 'does not equal', needsValue: true },
  { id: 'lt', label: 'is below (number)', needsValue: true },
  { id: 'gt', label: 'is above (number)', needsValue: true },
  { id: 'one_of', label: 'is one of (comma list)', needsValue: true },
  { id: 'not_one_of', label: 'is not one of (comma list)', needsValue: true },
] as const;

export const effectLabels: Readonly<Record<PolicyEffect, string>> = {
  deny: 'deny: block the action',
  require_approval: 'require_approval: hold the action for a human decision',
  alert: 'alert: let the action through and raise an alert',
  allow: 'allow: permit only what matches (everything else is denied)',
};

export const enforcementLabels: Readonly<Record<EnforcementPoint, string>> = {
  pre_merge: 'pre_merge: on every pull request',
  deploy: 'deploy: before a version is deployed or released',
  runtime: 'runtime: at the point of action (gateway or guardrail)',
  periodic: 'periodic: on a schedule, over what is already running',
};

