/** The template for `id`; throws on an unknown id so a page cannot render the wrong one. */
export function policyCardTemplateById(id: string): PolicyCardTemplate {
  const template = policyCardTemplates.find((entry) => entry.id === id);
  if (!template) throw new Error(`policy-card.ts: no template with id "${id}"`);
  return template;
}
